// Temporary smoke test (to be deleted). Verifies click -> toast -> auto-hide.
import { describe, it, expect, beforeAll } from 'vitest';
import * as React from 'react';
import { createRoot } from 'react-dom/client';
import { act } from 'react';
import { ThemeProvider } from '@gravity-ui/uikit';
import { App } from './App';

beforeAll(() => {
  (globalThis as any).IS_REACT_ACT_ENVIRONMENT = true;
  if (!(globalThis as any).ResizeObserver) {
    (globalThis as any).ResizeObserver = class { observe() {} unobserve() {} disconnect() {} };
  }
  if (!window.matchMedia) {
    (window as any).matchMedia = () => ({ matches: false, addListener() {}, removeListener() {}, addEventListener() {}, removeEventListener() {} });
  }
});

describe('notify button', () => {
  it('shows a toast on click and auto-hides it', async () => {
    const container = document.createElement('div');
    document.body.appendChild(container);
    const root = createRoot(container);
    await act(async () => {
      root.render(<ThemeProvider theme="light"><App /></ThemeProvider>);
    });

    const button = [...document.querySelectorAll('button')].find(b => b.textContent?.includes('Показать уведомление'));
    expect(button).toBeTruthy();

    await act(async () => { button!.click(); });
    expect(document.body.textContent).toContain('Кнопка нажата 1 раз(а)');

    await act(async () => { button!.click(); });
    expect(document.body.textContent).toContain('Кнопка нажата 2 раз(а)');

    // Wait past the configured 4000 ms auto-hide.
    await act(async () => { await new Promise(r => setTimeout(r, 4300)); });
    const toastEls = [...document.querySelectorAll('[data-toast]')];
    console.log('toasts still mounted at 4.3s:', toastEls.length,
      'classes:', toastEls.map(t => t.className));

    // jsdom runs no CSS animations, so simulate the browser's animationend
    // that Gravity's ToastList waits for before unmounting exiting toasts.
    await act(async () => {
      toastEls.forEach(el => el.dispatchEvent(new Event('animationend')));
      await new Promise(r => setTimeout(r, 50));
    });
    expect(document.querySelectorAll('[data-toast]').length).toBe(0);
    expect(document.body.textContent).not.toContain('Кнопка нажата');

    await act(async () => { root.unmount(); });
  }, 15000);
});

